unsigned checks{},negatives{};
void check(bool value,const char* why){++checks;if(!value)throw FormatError(why);}
void u16(std::vector<std::byte>& v,unsigned at,unsigned x){v.at(at)=std::byte(x);v.at(at+1)=std::byte(x>>8);}
void u32(std::vector<std::byte>& v,unsigned at,unsigned x){for(unsigned i=0;i<4;++i)v.at(at+i)=std::byte(x>>(8*i));}
struct Input {
    unsigned opaque=2,transparent=1,nodes=4,count=2;
    std::vector<std::byte> header=std::vector<std::byte>(120),descriptors=std::vector<std::byte>(96),positions,uv=std::vector<std::byte>(16),basis=std::vector<std::byte>(72),map{std::byte{0},std::byte{1},std::byte{2},std::byte{3}},parts=std::vector<std::byte>(144),indices=std::vector<std::byte>(4);
    explicit Input(unsigned maximum=2):opaque(maximum){
        const unsigned stride=maximum==1?16:20;positions.resize(count*stride);
        descriptors[0]=std::byte(maximum*2);descriptors[1]=std::byte(stride);
        descriptors[32]=std::byte{23};descriptors[33]=std::byte{8};descriptors[64]=std::byte{25};descriptors[65]=std::byte{36};
        u32(header,0,2);u32(header,0x20,2);u16(parts,0,2);u16(parts,6,0);u16(parts,8,1);u16(parts,72,5);u16(parts,78,1);u16(parts,80,1);u16(indices,0,0);u16(indices,2,1);
        for(unsigned v=0;v<count;++v){u32(positions,v*stride,std::bit_cast<unsigned>(.25f));u32(positions,v*stride+4,std::bit_cast<unsigned>(-.5f));u32(positions,v*stride+8,std::bit_cast<unsigned>(.75f));for(unsigned lane=0;lane<4;++lane)positions[v*stride+12+lane]=std::byte(lane);if(maximum>1)for(unsigned lane=0;lane<4;++lane)positions[v*stride+16+lane]=std::byte(std::array{251,250,200,100}[lane]);}
    }
    MccSkinnedModelVertexLayout run()const{return project_mcc_skinned_model_vertex_layout(opaque,transparent,nodes,count,header,descriptors,positions,uv,basis,map,parts,indices);}
};
std::array<float,4> fetch(std::span<const std::byte> bytes,unsigned at,unsigned count){std::array<float,4> out{0,0,0,1};for(unsigned i=0;i<count;++i)out[i]=float(std::to_integer<unsigned>(bytes[at+i]))/255.f;return out;}
void portable(){
    for(unsigned maximum=1;maximum<=4;++maximum){Input f(maximum);const auto source=f;const auto out=f.run();const auto stride=maximum<=2?16:20;check(out.descriptors[0]==std::byte(maximum*2+1) && out.descriptors[1]==std::byte(stride) && out.descriptors[32]==std::byte{24} && out.descriptors[64]==std::byte{27},"Original FLOAT/UB_OGL declaration differs");check(out.positions.size()==f.count*stride,"Projected position extent differs");
        for(unsigned v=0;v<f.count;++v){const unsigned old_stride=maximum==1?16:20;check(std::equal(f.positions.begin()+v*old_stride,f.positions.begin()+v*old_stride+12,out.positions.begin()+v*stride),"Literal normalized FLOAT positions changed");check(fetch(f.positions,v*old_stride+12,maximum)==fetch(out.positions,v*stride+12,maximum),"Stored index lanes or default lanes changed");if(maximum>1)check(fetch(f.positions,v*old_stride+16,maximum)==fetch(out.positions,v*stride+(maximum==2?14:16),maximum),"Stored weight lanes/defaults were normalized or completed");}
        check(f.positions==source.positions && f.header==source.header && f.parts==source.parts && f.indices==source.indices && f.descriptors==source.descriptors,"Pure projection mutated an input");const auto again=f.run();check(out.positions==again.positions && out.basis==again.basis && out.descriptors==again.descriptors && out.node_map==again.node_map,"Repeated projection changed");
    }
    const auto reject=[&](auto mutate){Input f;mutate(f);bool threw=false;try{(void)f.run();}catch(const FormatError&){threw=true;}check(threw,"Unsupported skinned source was admitted");++negatives;};
    for(unsigned n:{0,119,121})reject([&](Input& f){f.header.resize(n);});
    reject([](Input& f){f.opaque=0;f.transparent=0;});reject([](Input& f){f.opaque=5;});reject([](Input& f){f.transparent=5;});reject([](Input& f){f.nodes=0;});reject([](Input& f){f.nodes=257;});reject([](Input& f){f.count=0;});reject([](Input& f){f.count=65536;});
    reject([](Input& f){f.descriptors[0]=std::byte{6};});reject([](Input& f){f.descriptors[1]=std::byte{16};});reject([](Input& f){f.descriptors[2]=std::byte{1};});reject([](Input& f){f.descriptors.pop_back();});reject([](Input& f){f.positions.pop_back();});reject([](Input& f){f.uv.pop_back();});reject([](Input& f){f.basis.pop_back();});
    reject([](Input& f){f.map.resize(257);});reject([](Input& f){f.map[0]=std::byte{4};});reject([](Input& f){f.positions[13]=std::byte{4};});reject([](Input& f){f.positions[32]=std::byte{4};});reject([](Input& f){f.parts.clear();});reject([](Input& f){f.parts.pop_back();});reject([](Input& f){u32(f.header,0,1);});reject([](Input& f){u32(f.header,0x20,65536);});reject([](Input& f){f.indices.pop_back();});reject([](Input& f){u16(f.parts,6,3);});reject([](Input& f){u16(f.parts,8,3);});reject([](Input& f){u16(f.indices,0,2);});reject([](Input& f){f.transparent=0;});reject([](Input& f){u32(f.positions,0,0x7f800000);});
    Input inactive(3);u16(inactive.parts,0,4);inactive.positions[13]=std::byte{255};inactive.positions[14]=std::byte{255};check(!inactive.run().positions.empty(),"Inactive opaque-only index lanes were falsely consumed by transparent one-influence part");
    Input direct;direct.map.clear();check(direct.run().node_map.empty(),"Explicit direct node domain invented a map");
}
struct Row{unsigned cls{},opaque{},transparent{},count{},flags{},ordinal{};std::vector<std::byte> header;std::vector<MenuWorldSourceResource> resources;};
std::vector<Row> rows(const Cache& cache,const Tag& tag){const auto m=cache.load_source_tag_metadata(tag.datum);const Bytes root(m.bytes_at(m.source_address(),0x68));const auto raw=cache.load_model_resources(tag.datum);std::vector<Row> out;for(unsigned i=0;i<root.u32(0x24);++i){const Bytes s(m.bytes_at(root.u32(0x28)+i*92,92));if(!s.u16(4))continue;const Bytes b(raw.at(i));const auto base=raw.at(i).size()-s.u32(0x44)-4;Row r{s.u16(0),std::to_integer<unsigned>(s.slice(0x14,1)[0]),std::to_integer<unsigned>(s.slice(0x15,1)[0]),s.u16(4),s.u16(0x1a),i,{},{}};const auto h=b.slice(8,base-8);r.header.assign(h.begin(),h.end());for(unsigned k=0;k<s.u32(0x48);++k){const Bytes d(m.bytes_at(s.u32(0x4c)+k*16,16));const auto data=b.slice(base+d.u32(12),d.u32(8));r.resources.push_back({d.u16(4),d.u16(6),unsigned(base+d.u32(12)),{data.begin(),data.end()}});}out.push_back(std::move(r));}return out;}
const MenuWorldSourceResource& resource(const Row& r,unsigned type,unsigned channel){const MenuWorldSourceResource* result=nullptr;for(const auto& x:r.resources)if(x.type==type && x.channel==channel){check(!result,"Duplicate typed model resource");result=&x;}check(result,"Missing typed model resource");return *result;}
std::set<unsigned> startup(const Cache& c,bool multiplayer){const auto content=c.load_content(0,multiplayer);std::set<unsigned> models;const auto add=[&](unsigned model){if(model!=null_datum)models.insert(model);};for(const auto&o:content.objects){if(o.type==1 && o.definition!=null_datum)add(c.load_initial_model_definition(o.definition).render_model);if(o.type==11 && o.definition!=null_datum){const auto d=c.load_source_prop_definition(o.definition);check(d.constructor_admitted,"Startup prop lacks actual constructor owner");add(d.render_model);}}for(const auto&[id,w]:content.weapons)if(!w.first_person_models.empty() && w.first_person_models[0].model!=null_datum && w.first_person_models[0].animation!=null_datum)add(c.load_initial_model_definition(id).render_model);for(const auto&r:content.player_representations)if(r.biped.model!=null_datum){const auto m=c.load_source_tag_metadata(r.biped.model);add(Bytes(m.bytes_at(m.source_address(),m.size())).u32(4));}return models;}
void same_ranges(const SourceBspRangeGeometry& a,const SourceBspRangeGeometry& b){check(a.part_count==b.part_count && a.subpart_count==b.subpart_count && a.accelerator_count==b.accelerator_count && a.index_count==b.index_count && a.parts==b.parts && a.subparts==b.subparts && a.accelerator==b.accelerator && a.mapping==b.mapping && a.bounds.size()==b.bounds.size(),"Actual source/projected range consumers differ");for(unsigned i=0;i<a.bounds.size();++i){const auto& x=a.bounds[i];const auto& y=b.bounds[i];for(const auto [p,q]:{std::pair{x.center.x,y.center.x},std::pair{x.center.y,y.center.y},std::pair{x.center.z,y.center.z},std::pair{x.radius,y.radius}})check(std::bit_cast<unsigned>(p)==std::bit_cast<unsigned>(q),"Source bound float changed");check(x.node==y.node,"Source bound node changed");}}
Json actual(const char* path,const char* original_path,const char* cpu_path){
    Cache cache(path);check(cache.is_mcc(),"Actual source must be MCC");std::unique_ptr<Cache> original;if(original_path)original=std::make_unique<Cache>(original_path);Json cpu=Json::object();if(cpu_path){std::ifstream file(cpu_path);file>>cpu;check(cpu.at("original_xbe_sha256")=="21b207e7efdacaf6124a0822837f8be570766a42505057f7fd2d2ba8f409c4fd","Wrong TU1.5 CPU authority");}
    unsigned owners{},sections{},skinned{},vertices{},mixed{},paired{},active_lanes{},default_lanes{},cpu_cases{},declaration_cases{},range_cases{},direct_node_sections{};std::set<unsigned> widths;
    const bool multiplayer=cache.name()=="lockout";
    check(multiplayer || cache.name()=="00a_introduction","Startup model inventory requires its explicit MCC map profile");
    for(const auto id:startup(cache,multiplayer)){const auto* tag=cache.query_tag({.handle=TagHandle{id},.group=tag_groups::render_model,.require_address=true});check(tag,"Startup lost typed full-salt model");const auto meta=cache.load_source_tag_metadata(id);const unsigned nodes=Bytes(meta.bytes_at(meta.source_address(),0x4c)).u32(0x48);const auto source=rows(cache,*tag);++owners;std::vector<Row> reference;if(original && (tag->name=="objects\\characters\\masterchief\\masterchief" || tag->name=="objects\\characters\\elite\\elite")){const auto* t=original->query_tag({.group=tag_groups::render_model,.name=tag->name,.require_address=true});check(t,"Missing exact named Original actor model");reference=rows(*original,*t);}
        for(const auto& row:source){const auto adapter=load_menu_world_source_model_section(cache,id,row.ordinal);++sections;check(adapter.owner_datum()==id && adapter.section()==row.ordinal && adapter.model_geometry_class()==row.cls && adapter.vertex_count()==row.count && adapter.compression_flags()==row.flags,"Actual typed model/section identity changed");check(row.header.size()==120 && std::ranges::equal(row.header,adapter.raw_model_header()),"Actual120-byte header changed");if(std::none_of(row.resources.begin(),row.resources.end(),[](const auto& r){return r.type==104;})){check(adapter.node_map().empty(),"Absent source node bank was fabricated");const auto& raw=resource(row,56,0).bytes;const unsigned stride=row.cls==1?12:16;if(row.cls==2)for(unsigned v=0;v<row.count;++v)check(std::to_integer<unsigned>(raw[v*stride+12])<nodes,"Actual direct model-node index escapes root hierarchy");++direct_node_sections;}if(row.cls!=3)continue;
            ++skinned;vertices+=row.count;const unsigned maximum=std::max(row.opaque,row.transparent);widths.insert(maximum);const auto& positions=resource(row,56,0);const auto& parts=resource(row,0,72);const auto& indices=resource(row,32,2);const auto out=project_mcc_skinned_model_vertex_layout(row.opaque,row.transparent,nodes,row.count,row.header,resource(row,56,32).bytes,positions.bytes,resource(row,56,1).bytes,resource(row,56,2).bytes,resource(row,104,1).bytes,parts.bytes,indices.bytes);
            check(std::ranges::equal(adapter.node_map(),out.node_map),"Actual node104 bank changed");check(adapter.resources().size()==row.resources.size(),"Actual resource count changed");for(unsigned i=0;i<row.resources.size();++i){const auto& before=row.resources[i];const auto& after=adapter.resources()[i];auto expected=before.bytes;if(before.type==56 && before.channel==0)expected=out.positions;if(before.type==56 && before.channel==2)expected=out.basis;if(before.type==56 && before.channel==32)std::copy(out.descriptors.begin(),out.descriptors.end(),expected.begin());check(before.type==after.type && before.channel==after.channel && before.raw_offset==after.raw_offset && expected==after.bytes,"Projection changed unrelated resource ownership/bytes");}
            same_ranges(load_source_model_range_geometry(cache,id,row.ordinal),source_model_range_geometry(adapter));++range_cases;
            bool opaque_part=false,transparent_part=false;for(unsigned at=0;at<parts.bytes.size();at+=72){const auto kind=Bytes(parts.bytes).u16(at);const bool transparent=kind==4 || kind==5;if(transparent)transparent_part=true;else opaque_part=true;
                if(cpu_path){const unsigned active=transparent?row.transparent:row.opaque;const auto& declarations=cpu.at("declarations");const auto it=std::find_if(declarations.begin(),declarations.end(),[&](const auto& d){return d.at("classification")==active+2 && d.at("stream_types").at(0)==maximum*2+1;});check(it!=declarations.end(),"Missing genuine mixed-part declaration case");const auto semantics=it->at("semantics").template get<std::vector<unsigned>>();for(unsigned reg=0;reg<semantics.size();++reg){const auto semantic=SourceVertexSemantic(semantics[reg]);const auto stream=std::find_if(adapter.streams().begin(),adapter.streams().end(),[&](const auto& s){return s.semantic==semantic;});check(stream!=adapter.streams().end(),"Actual projected declaration lacks an Original semantic");const auto expected=it->at("registers").at(reg).template get<std::array<unsigned,4>>();const auto& r=adapter.resources().at(stream->resource);check(r.type==56 && r.channel==expected[0] && stream->byte_offset==expected[1],"Actual mixed-part fetch channel/offset differs from whole Original1C310");const auto format=expected[2]==0x32?MenuWorldSourceFormat::float32x3:expected[2]==0x22?MenuWorldSourceFormat::float32x2:expected[2]==0x16?MenuWorldSourceFormat::packed_signed_11_11_10:std::array{MenuWorldSourceFormat::unorm8x1,MenuWorldSourceFormat::unorm8x2,MenuWorldSourceFormat::unorm8x3,MenuWorldSourceFormat::unorm8x4}.at((expected[2]>>4)-1);check(stream->format==format,"Actual mixed-part fetch width/normalization differs from whole Original1C310");}++declaration_cases;}
            }mixed+=opaque_part && transparent_part && row.opaque!=row.transparent;
            for(const auto& expected:cpu.value("compression",Json::array()))if(expected.at("model")==id && expected.at("section")==row.ordinal){for(unsigned i=0;i<12;++i)check(std::bit_cast<unsigned>(adapter.compression_rows()[i])==expected.at("constants").at(i),"Skinned c170 differs from genuine Original arithmetic on actual MCC bounds");++cpu_cases;}
            if(!reference.empty()){const auto it=std::find_if(reference.begin(),reference.end(),[&](const auto& x){return x.ordinal==row.ordinal;});check(it!=reference.end() && it->count==row.count && it->cls==3 && it->opaque==row.opaque && it->transparent==row.transparent,"Paired Original section identity/influence tuple differs");const auto& old=resource(*it,56,0).bytes;const Bytes d(resource(*it,56,32).bytes);const unsigned old_type=std::to_integer<unsigned>(d.slice(0,1)[0]),old_stride=std::to_integer<unsigned>(d.slice(1,1)[0]);check(old_type==maximum*2+2,"Paired Original compressed layout differs");const unsigned old_index=maximum==2 || maximum==4?8:6,new_stride=maximum<=2?16:20;for(unsigned v=0;v<row.count;++v){check(fetch(old,v*old_stride+old_index,maximum)==fetch(out.positions,v*new_stride+12,maximum),"Paired Original complete UB_OGL index fetch/default lanes differ");check(fetch(old,v*old_stride+old_index+maximum,maximum)==fetch(out.positions,v*new_stride+(maximum==2?14:16),maximum),"Paired Original complete UB_OGL weight fetch/default lanes differ");active_lanes+=maximum*2;default_lanes+=(4-maximum)*2;}check(resource(*it,100,1).bytes==resource(row,104,1).bytes,"Paired actual node map changed");check(resource(*it,56,2).bytes==out.basis,"Paired Original physical packed N/T/B differs");++paired;}
        }
        const auto after=rows(cache,*tag);check(after.size()==source.size(),"Source model section bank mutated");for(unsigned i=0;i<source.size();++i){check(source[i].header==after[i].header && source[i].resources.size()==after[i].resources.size(),"Source header/resource count mutated");for(unsigned r=0;r<source[i].resources.size();++r)check(source[i].resources[r].bytes==after[i].resources[r].bytes,"Source resource bytes mutated");}
    }
    // The frozen24/131 inventory is Lockout's startup, not the opening's.
    // The opening check below still visits every actual startup owner/section
    // and verifies its complete streams, ranges, node ownership and source
    // preservation above. It makes no fixed-count or cinematic-pose claim.
    if(cache.name()=="00a_introduction") {
        check(owners && sections && skinned,"MCC opening startup exercised no skinned model owners");
        check(!original && !cpu_path,"Opening model inventory has no paired Lockout reference profile");
    } else {
        check(cache.name()=="lockout","Startup model inventory requires its explicit MCC map profile");
        check(owners==24 && sections==131 && skinned==12 && mixed==2 && direct_node_sections==3,"Actual startup model/influence coverage changed");
        if(original)check(paired==12,"Incomplete paired actor section coverage");
        if(cpu_path)check(cpu_cases==12 && declaration_cases,"Incomplete genuine TU1.5 compression/declaration proof");
    }
    return {{"map",cache.name()},{"startup_models",owners},{"startup_sections",sections},{"skinned_sections",skinned},{"skinned_vertices",vertices},{"stored_widths",widths},{"mixed_opaque_transparent_sections",mixed},{"paired_original_sections",paired},{"paired_literal_index_weight_lanes",active_lanes},{"paired_default_fetch_lanes",default_lanes},{"original_cpu_compression_cases",cpu_cases},{"original_cpu_declaration_part_cases",declaration_cases},{"source_range_consumer_cases",range_cases},{"actual_direct_model_node_sections",direct_node_sections},{"source_resources_unchanged",true},{"mesh_precision_or_GPU_parity_claim",false}};
}
