int main(int argc,char** argv)try{portable();Json out;if(argc>1){for(int i=1;i<argc;++i)if(std::string(argv[i]).empty() || !std::filesystem::is_regular_file(argv[i]))return 77;out=actual(argv[1],argc>2?argv[2]:nullptr,argc>3?argv[3]:nullptr);}std::cout<<Json{{"checks",checks},{"negative_cases",negatives},{"actual",out}}.dump()<<'\n';return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
